import json, subprocess
MOD=1<<64
def fp(b):
    h=0
    for c in b: h=(h*257+c+1)%MOD
    return {'n':len(b),'h':'%016x'%h}
def run(cases, events, timeout=10):
    d = {"seed":"s","definitions":[],"timeout_ms":timeout,"cases":cases,"events":events,"channels":[]}
    p = subprocess.run(['python3','-B','main.py'], input=json.dumps(d).encode(), capture_output=True, cwd='/workspace/project')
    if p.returncode: print('EXIT', p.stderr.decode()[:400]); return None
    return json.loads(p.stdout.decode())
def C(name, frames):
    return {"name":name,"frames":frames,"expect":{"method":"GET","target":"/","host":"h"}}
def H(end=False, pairs=None):
    return {"Type":"headers","data_to_transfered":pairs or [["a","b"]],"End_Stream":end}
def D(data="x", end=False):
    return {"Type":"data","data_to_transfered":data,"End_Stream":end}
def S(ms):
    return {"Type":"sleep","Time_to_Stop":ms}
def E(at, kind="headers", stream=0, end=True, data="q", fields=None):
    if kind=="close": return {"at":at,"kind":"close"}
    if kind=="headers": return {"at":at,"kind":"headers","stream":stream,"fields":fields or [["s","v"]],"end":end}
    return {"at":at,"kind":"data","stream":stream,"data":data,"end":end}
def show(name, out):
    print(name)
    for c in out['cases']:
        print('  ', c['name'], c['state'], 'at', c['at'], 'frames', c['frames'], 'rf', c['request_frames'],
              'sent', c['sent']['n'], 'recv', c['received']['n'], 'rframes', c['response_frames'], 'rbody', c['response_body']['n'])

show('tied response wins', run([C('a',[])], [E(10)]))
show('tied close wins over timeout', run([C('a',[])], [E(10,kind='close')]))
show('close before timeout', run([C('a',[])], [E(5,kind='close')]))
show('plain timeout', run([C('a',[])], []))
show('zero pause yields to events', run([C('a',[H(),S(0),D()])], [E(0)]))
show('response during pause', run([C('a',[H(),S(5),D()])], [E(2)]))
show('close during pause', run([C('a',[H(),S(5),D()])], [E(3,kind='close')]))
show('close at 0', run([C('a',[H(),D()]),C('b',[S(4)])], [E(0,kind='close')]))
